/// Marquee (rubber-band) select every element inside the screen rect (Alt+drag).
pub fn meshEditBox(x0: f32, y0: f32, x1: f32, y1: f32, additive: bool) i32 {
    if (z3d.g_paint_session) return -1; // req_2662: paint owns the drag — no marquee selects
    if (!model_paint.hasTarget()) return -1;
    const cam = model_paint.Camera{ .eye = z3d.g_paint_eye, .target = z3d.g_paint_target, .fov_deg = z3d.g_paint_fov };
    return mesh_edit.boxSelect(cam, z3d.g_paint_vp_w, z3d.g_paint_vp_h, z3d.vpLocalX(x0), z3d.vpLocalY(y0), z3d.vpLocalX(x1), z3d.vpLocalY(y1), additive);
}
/// Snapshot the selection before an instant mousedown pick; revert if the press drags.
pub fn meshEditSnapshot() void {
    mesh_edit.snapshotSelection();
}
pub fn meshEditRevert() void {
    mesh_edit.revertSelection();
}
/// Select a face by index (no raycast) — programmatic / headless. Returns true on success.
pub fn meshEditSelectFace(idx: u32, additive: bool) bool {
    if (z3d.g_paint_session) return false; // req_2662: selection doors are inert in paint mode
    return mesh_edit.selectFaceByIndex(idx, additive);
}

/// Replace the authored-face selection from one complete character-rig audit
/// result. The session computes and selects against the same resident RJMD
/// snapshot in one host-door call, so a detached/uncovered count cannot race a
/// later JavaScript face loop.
pub fn characterRigSelectFaces(face_indices: []const u32) u32 {
    if (z3d.g_paint_session) return 0;
    const face_count: usize = @intCast(z3d.g_edit_count / 3);
    if (face_count == 0) return 0;
    const mask = std.heap.c_allocator.alloc(bool, face_count) catch return 0;
    defer std.heap.c_allocator.free(mask);
    @memset(mask, false);
    for (face_indices) |face_index| {
        const triangle_index: usize = @intCast(face_index);
        if (triangle_index >= face_count) return 0;
        mask[triangle_index] = true;
    }
    return mesh_edit.selectFacesByTriangleMask(mask);
}
/// Select a welded vertex by stable topology index (no raycast).
pub fn meshEditSelectVertex(idx: u32, additive: bool) bool {
    if (z3d.g_paint_session) return false;
    return mesh_edit.selectVertexByIndex(idx, additive);
}
