pub fn meshEditSetFaceGroups(groups: []const u32) void {
    if (!z3d.residentMutationAllowed(.durable_channels)) return;
    z3d.clearIndexedEditMesh();
    model_source.setFaceGroups(groups);
    mesh_edit.faceGroupsChanged();
