pub const MeshSemanticRestoreResult = union(enum) {
    restore: u32,
    refuse: mesh_semantic_restore.Refusal,
};

/// Restore the semantic channel without treating saved geometry as a fallback
/// source. This is a narrow recovery capability for the state where hydration
/// lost names but every saved named triangle still exists uniquely in the live
/// resident. It never guesses by proximity and never overwrites a named face.
pub fn meshSemanticRestoreFromDocument(
    candidate_verts: []const f32,
    candidate_regions: ?[]const u32,
    candidate_instances: ?[]const u32,
    candidate_table_json: ?[]const u8,
) z3d.MeshSemanticRestoreResult {
    if (!z3d.residentMutationAllowed(.durable_channels)) return .{ .refuse = .historical_preview_active };
    // Hidden blocks have their own source-order row arrays. With none present,
    // model_source is the complete resident document and—unlike the save
    // snapshot's opaque/glass ordering—its face order is exactly the order the
    // installed semantic rows must address.
    const resident_verts_all = model_source.verts() orelse
        return .{ .refuse = .no_resident_document };
    const resident_len = std.math.mul(usize, model_source.count(), 8) catch
        return .{ .refuse = .no_resident_document };
    if (resident_len == 0 or resident_verts_all.len < resident_len)
        return .{ .refuse = .no_resident_document };
    const decision = mesh_semantic_restore.evaluate(std.heap.c_allocator, .{
        .verts = candidate_verts,
        .semantic_regions = candidate_regions,
        .semantic_instances = candidate_instances,
        .semantic_table_json = candidate_table_json,
    }, .{
        .verts = resident_verts_all[0..resident_len],
        .semantic_regions = model_source.faceSemanticRegions(),
        .semantic_instances = model_source.faceSemanticInstances(),
        .semantic_table_json = model_source.semanticTableJson(),
        .hidden_part_count = z3d.g_hidden_groups.items.len,
    });
    var plan = switch (decision) {
        .refuse => |reason| return .{ .refuse = reason },
        .restore => |value| value,
    };
    defer plan.deinit(std.heap.c_allocator);
    const table_json = candidate_table_json orelse return .{ .refuse = .candidate_semantics_invalid };
    if (!model_source.setSemanticState(plan.semantic_regions, plan.semantic_instances, table_json))
        return .{ .refuse = .install_failed };
    z3d.clearIndexedEditMesh();
    return .{ .restore = plan.restored_named_faces };
}

/// Author meaning onto the current face selection. Membership and dictionary
/// commit in the same journal unit, so undo/redo can never pair ids with the
/// wrong names. Returns changed render triangles (zero is a refusal/no-op).
pub fn meshSemanticAssignSelection(region: u32, instance: u32, table_json: []const u8) u32 {
    if (!z3d.residentMutationAllowed(.durable_channels)) return 0;
    if (region == model_source.NO_SEMANTIC_ID or !model_paint.hasTarget() or mesh_edit.mode() != .face) return 0;
    const face_count = z3d.g_edit_count / 3;
    if (face_count == 0) return 0;
    const mask = z3d.jalloc.alloc(bool, face_count) catch return 0;
    defer z3d.jalloc.free(mask);
    if (mesh_edit.buildDeleteMask(mask) == 0) return 0;
    var rows = z3d.captureFaceSemantics(face_count) orelse return 0;
    defer rows.deinit();
    // Track which TRIANGLES changed, but report AUTHORED FACES: the caller prints this
    // number to the user next to the word "faces", and a quad is one face, not two
    // (req_3888 — naming one quad announced "named 2 faces").
    const changed_mask = z3d.jalloc.alloc(bool, face_count) catch return 0;
    defer z3d.jalloc.free(changed_mask);
    @memset(changed_mask, false);
    var changed: u32 = 0;
    for (mask, 0..) |selected, face| {
        if (!selected) continue;
        if (rows.regions[face] == region and rows.instances[face] == instance) continue;
        rows.regions[face] = region;
        rows.instances[face] = instance;
        changed_mask[face] = true;
        changed += 1;
    }
    if (changed == 0) return 0;
    var snap = z3d.journalSnapshotCurrent("name faces");
    if (!model_source.setSemanticState(rows.regions, rows.instances, table_json)) {
        z3d.journalDiscard(&snap);
        return 0;
    }
    z3d.clearIndexedEditMesh();
    z3d.journalCommit(&snap);
    return mesh_edit.authoredFacesInMask(changed_mask);
}

/// Name one selected authored edge chain/loop. Logical endpoint identity and the
/// stable Outliner object id enter one native journal transaction; edge table indices
/// and coordinates never enter the durable row. Caller owns the JSON receipt.
pub fn meshEdgeSemanticAssignSelection(
    allocator: std.mem.Allocator,
    name: []const u8,
    role_text: []const u8,
    object_id: []const u8,
) ?[]u8 {
    if (!z3d.residentMutationAllowed(.durable_channels)) return null;
    if (!model_paint.hasTarget() or mesh_edit.mode() != .edge) return null;
    const edge_count = mesh_edit.selectedEdgeCountPub();
    if (edge_count == 0) return null;
    const selected = allocator.alloc(mesh_edit.Edge, edge_count) catch return null;
    defer allocator.free(selected);
    if (mesh_edit.selectedEdgesPub(selected) != edge_count) return null;
    const part = mesh_edit.selectedEdgesCommonPartPub() orelse return null;
    const role = mesh_edge_semantics.Role.parse(role_text) orelse return null;
    var snap = z3d.journalSnapshotCurrent("name edge region");
    if (snap == null) return null;
    const promotion = z3d.prepareLogicalTopologyForEdgeAuthoring() orelse {
        z3d.journalDiscard(&snap);
        return null;
    };
    var committed = false;
    defer if (!committed) {
        z3d.journalDiscard(&snap);
        z3d.rollbackEdgeLogicalPromotion(promotion);
    };
    const path_edges = allocator.alloc(mesh_edge_semantics.Edge, edge_count) catch return null;
    defer allocator.free(path_edges);
    for (selected, 0..) |edge, index| {
        const a = z3d.stableLogicalIdForEditVertex(edge[0]) orelse {
            z3d.journalDiscard(&snap);
            return null;
        };
        const b = z3d.stableLogicalIdForEditVertex(edge[1]) orelse {
            z3d.journalDiscard(&snap);
            return null;
        };
        path_edges[index] = .{ .a = a, .b = b, .part = part };
    }
    var path = mesh_edge_semantics.canonicalPathAlloc(allocator, path_edges) catch {
        z3d.journalDiscard(&snap);
        return null;
    };
    defer path.deinit();
    const table_json = model_source.semanticTableJson() orelse z3d.EMPTY_SEMANTIC_TABLE_JSON;
    var assigned = mesh_edge_semantics.appendRegionAlloc(allocator, table_json, name, role, object_id, path) catch {
        z3d.journalDiscard(&snap);
        return null;
    };
    defer assigned.deinit();
    if (!z3d.edgeSemanticTableResolvesInCurrentDocument(allocator, assigned.json)) {
        z3d.journalDiscard(&snap);
        return null;
    }
    var rows = z3d.captureFaceSemantics(z3d.g_edit_count / 3) orelse return null;
    defer rows.deinit();
    const receipt = std.json.Stringify.valueAlloc(allocator, .{
        .ok = true,
        .id = assigned.id,
        .name = name,
        .role = role.text(),
        .objectId = object_id,
        .edges = edge_count,
        .vertices = path.vertices.len,
        .closed = path.closed,
    }, .{}) catch return null;
    if (!model_source.setSemanticState(rows.regions, rows.instances, assigned.json)) {
        allocator.free(receipt);
        z3d.journalDiscard(&snap);
        return null;
    }
    z3d.journalCommit(&snap);
    committed = true;
    return receipt;
}

/// Restore one durable edge region to the current edge selection by logical endpoint
/// pairs. A stale/mutated path changes nothing and returns zero.
pub fn meshEdgeSemanticSelect(region_id: u32, additive: bool) u32 {
    const table_json = model_source.semanticTableJson() orelse return 0;
    var region = mesh_edge_semantics.regionByIdAlloc(z3d.jalloc, table_json, region_id) catch return 0;
    defer region.deinit();
    const edge_count = region.vertices.len - 1 + @as(usize, if (region.closed) 1 else 0);
    const pairs = z3d.jalloc.alloc(mesh_edit.Edge, edge_count) catch return 0;
    defer z3d.jalloc.free(pairs);
    const edit_vertices = z3d.jalloc.alloc(u32, region.vertices.len) catch return 0;
    defer z3d.jalloc.free(edit_vertices);
    for (region.vertices, 0..) |stable_id, index| {
        const edit_vertex = z3d.editVertexForStableLogicalId(stable_id) orelse return 0;
        // A position-weld edit handle may cover two deliberately split v5 ids. In
        // that case the viewport cannot select one honestly, so refuse instead of
        // highlighting a different durable edge.
        if (z3d.stableLogicalIdForEditVertex(edit_vertex) != stable_id) return 0;
        edit_vertices[index] = edit_vertex;
    }
    for (0..edit_vertices.len - 1) |index| pairs[index] = .{ edit_vertices[index], edit_vertices[index + 1] };
    if (region.closed) pairs[pairs.len - 1] = .{ edit_vertices[edit_vertices.len - 1], edit_vertices[0] };
    return mesh_edit.selectEdgesByEndpointPairsPub(pairs, additive);
}

/// Edit ONE existing semantic region: RENAME it (membership untouched — only the
/// caller's rewritten table lands) or REMOVE it (every face wearing it becomes
/// unnamed and the row leaves the table).
///
/// Naming was a one-way door until now: a name could be created but never taken back
/// or corrected, so a mistyped or repurposed region was permanent (req_3894). Removal
/// clears BOTH the region and the instance to NO_SEMANTIC_ID, because a row carrying
/// an instance without a region is exactly what model_source rejects as invalid.
///
/// Returns the number of faces whose membership changed, or -1 when the edit was
/// refused. A rename legitimately changes zero faces, so the caller must test for
/// the negative rather than for zero.
pub fn meshSemanticRegionEdit(region: u32, remove: bool, table_json: []const u8) i32 {
    if (!z3d.residentMutationAllowed(.durable_channels)) return -1;
    if (region == model_source.NO_SEMANTIC_ID or !model_paint.hasTarget()) return -1;
    const face_count = z3d.g_edit_count / 3;
    if (face_count == 0) return -1;
    var rows = z3d.captureFaceSemantics(face_count) orelse return -1;
    defer rows.deinit();
    var changed: u32 = 0;
    if (remove) {
        for (rows.regions, rows.instances) |*face_region, *face_instance| {
            if (face_region.* != region) continue;
            face_region.* = model_source.NO_SEMANTIC_ID;
            face_instance.* = model_source.NO_SEMANTIC_ID;
            changed += 1;
        }
    }
    var snap = z3d.journalSnapshotCurrent(if (remove) "remove region" else "rename region");
    if (!model_source.setSemanticState(rows.regions, rows.instances, table_json)) {
        z3d.journalDiscard(&snap);
        return -1;
    }
    z3d.clearIndexedEditMesh();
    z3d.journalCommit(&snap);
    return @intCast(changed);
}

/// Name an untouched axis-aligned cube in one transaction. This is deliberately
/// strict (six authored faces, every normal axis-aligned, every side present), so
/// opening a legacy cube gives the seat known top/bottom/front/back/left/right
/// without mislabeling an arbitrary imported mesh.
pub fn meshSemanticBootstrapAxes(ids: [6]u32, table_json: []const u8) bool {
    if (!z3d.residentMutationAllowed(.durable_channels)) return false;
    if (model_source.faceSemanticRegions() != null or !model_paint.hasTarget()) return false;
    const verts = z3d.g_edit_verts orelse return false;
    const face_count: usize = @intCast(z3d.g_edit_count / 3);
    if (face_count < 6 or face_count > 12 or verts.len < face_count * 24) return false;
    var groups = std.AutoHashMapUnmanaged(u32, void).empty;
    defer groups.deinit(z3d.jalloc);
    const regions = z3d.jalloc.alloc(u32, face_count) catch return false;
    defer z3d.jalloc.free(regions);
    const instances = z3d.jalloc.alloc(u32, face_count) catch return false;
    defer z3d.jalloc.free(instances);
    @memset(instances, 0);
    var seen = [_]bool{false} ** 6;
    for (0..face_count) |face| {
        const group = model_source.faceGroupOf(@intCast(face));
        if (group == model_source.NO_FACE_GROUP) return false;
        _ = groups.getOrPut(z3d.jalloc, group) catch return false;
        const base = face * 24;
        const a = [3]f32{ verts[base], verts[base + 1], verts[base + 2] };
        const b = [3]f32{ verts[base + 8], verts[base + 9], verts[base + 10] };
        const c = [3]f32{ verts[base + 16], verts[base + 17], verts[base + 18] };
        const normal = z3d.normalOf(a, b, c);
        var axis: usize = 0;
        if (@abs(normal[1]) > @abs(normal[axis])) axis = 1;
        if (@abs(normal[2]) > @abs(normal[axis])) axis = 2;
        if (@abs(normal[axis]) < 0.99) return false;
        const side = axis * 2 + @as(usize, if (normal[axis] >= 0) 0 else 1);
        regions[face] = ids[side];
        seen[side] = true;
    }
    if (groups.count() != 6) return false;
    for (seen) |present| if (!present) return false;
    var snap = z3d.journalSnapshotCurrent("name primitive");
    if (!model_source.setSemanticState(regions, instances, table_json)) {
        z3d.journalDiscard(&snap);
        return false;
    }
    z3d.clearIndexedEditMesh();
    z3d.journalCommit(&snap);
    return true;
}

/// Name one newly-appended resident primitive by the generator roles known at its
/// creation boundary. Existing faces and their semantic ids remain untouched.
pub fn meshSemanticNamePrimitive(
    lo: u32,
    hi: u32,
    kind: mesh_semantics.PrimitiveKind,
    ids: []const u32,
    table_json: []const u8,
) bool {
    if (!z3d.residentMutationAllowed(.durable_channels)) return false;
    if (hi <= lo or ids.len != mesh_semantics.primitiveRoleCount(kind) or !model_paint.hasTarget()) return false;
    const verts = z3d.g_edit_verts orelse return false;
    const face_count: usize = @intCast(z3d.g_edit_count / 3);
    var rows = z3d.captureFaceSemantics(@intCast(face_count)) orelse return false;
    defer rows.deinit();
    var changed: u32 = 0;
    for (0..face_count) |face| {
        const group = model_source.faceGroupOf(@intCast(face));
        if (group == model_source.NO_FACE_GROUP or group < lo or group >= hi) continue;
        const base = face * 24;
        if (base + 24 > verts.len) return false;
        const a = [3]f32{ verts[base], verts[base + 1], verts[base + 2] };
        const b = [3]f32{ verts[base + 8], verts[base + 9], verts[base + 10] };
        const c = [3]f32{ verts[base + 16], verts[base + 17], verts[base + 18] };
        const role = mesh_semantics.primitiveRole(kind, z3d.normalOf(a, b, c)) orelse return false;
        if (role >= ids.len or ids[role] == model_source.NO_SEMANTIC_ID) return false;
        rows.regions[face] = ids[role];
        rows.instances[face] = 0;
        changed += 1;
    }
    if (changed == 0) return false;
    var snap = z3d.journalSnapshotCurrent("name primitive roles");
    if (!model_source.setSemanticState(rows.regions, rows.instances, table_json)) {
        z3d.journalDiscard(&snap);
        return false;
    }
    z3d.clearIndexedEditMesh();
    z3d.journalCommit(&snap);
    return true;
}

/// Stamp stable anatomy regions over complete outliner part ranges in one
/// journal transaction. `stamps` is a packed [lo, hi, region] sequence whose
/// group intervals must be ordered and disjoint. The caller owns the semantic
/// dictionary; native code owns face membership and refuses partial/ambiguous
/// range input rather than selecting through the UI.
pub fn meshSemanticStampPartRanges(stamps: []const u32, table_json: []const u8) i32 {
    if (!z3d.residentMutationAllowed(.durable_channels)) return -1;
    if (stamps.len == 0 or stamps.len % 3 != 0 or !model_paint.hasTarget()) return -1;
    if (z3d.g_hidden_groups.items.len != 0) return -1;
    const face_count: usize = @intCast(z3d.g_edit_count / 3);
    if (face_count == 0 or model_source.faceGroupOf(0) == model_source.NO_FACE_GROUP) return -1;
    var previous_hi: u32 = 0;
    for (0..stamps.len / 3) |index| {
        const lo = stamps[index * 3];
        const hi = stamps[index * 3 + 1];
        const region = stamps[index * 3 + 2];
        if (hi <= lo or (index != 0 and lo < previous_hi) or region == model_source.NO_SEMANTIC_ID) return -1;
        previous_hi = hi;
    }
    var rows = z3d.captureFaceSemantics(@intCast(face_count)) orelse return -1;
    defer rows.deinit();
    var changed: u32 = 0;
    var matched = z3d.jalloc.alloc(bool, stamps.len / 3) catch return -1;
    defer z3d.jalloc.free(matched);
    @memset(matched, false);
    for (0..face_count) |face| {
        const group = model_source.faceGroupOf(@intCast(face));
        for (0..stamps.len / 3) |index| {
            const lo = stamps[index * 3];
            const hi = stamps[index * 3 + 1];
            if (group < lo or group >= hi) continue;
            const region = stamps[index * 3 + 2];
            matched[index] = true;
            if (rows.regions[face] != region or rows.instances[face] != 0) {
                rows.regions[face] = region;
                rows.instances[face] = 0;
                changed += 1;
            }
            break;
        }
    }
    for (matched) |present| if (!present) return -1;
    var snap = z3d.journalSnapshotCurrent("stamp humanoid part roles");
    if (!model_source.setSemanticState(rows.regions, rows.instances, table_json)) {
        z3d.journalDiscard(&snap);
        return -1;
    }
    z3d.clearIndexedEditMesh();
    z3d.journalCommit(&snap);
    return @intCast(changed);
}

pub const SemanticPerceptAggregate = struct {
    faces: u32 = 0,
    instances: u32 = 0,
    min: [3]f32 = .{ std.math.inf(f32), std.math.inf(f32), std.math.inf(f32) },
    max: [3]f32 = .{ -std.math.inf(f32), -std.math.inf(f32), -std.math.inf(f32) },
};
/// The mesh the cached facts actually describe. Generation ALONE is not an identity:
/// replaceActiveEditMesh resets g_edit_generation to 1 on every load, quality re-mesh
/// and edit-replace, so a freshly opened model collides with the last one audited and
/// inherits its counts (req_3752 — a 12-triangle cube reported a moped's 890). The key
/// carries the model hash and the face count beside the generation, and every path that
/// swaps or drops the resident mesh clears it outright.
pub const AuditKey = struct { hash: u64, generation: u32, faces: u32, verts_digest: u64 };

pub fn invalidateMeshAudit() void {
    z3d.g_audit_key = null;
    z3d.g_audit_facts = .{};
}

pub fn meshAuditFacts(allocator: std.mem.Allocator, verts: []const f32, face_count: u32) mesh_audit.Facts {
    // The journal now advances generation for committed transforms, but live
    // previews patch positions before commit. Keep the vertex digest so a probe
    // during a preview never receives the prior intersection result (req_3763
    // P3-2); one Wyhash pass is trivial next to the audit.
    const key = z3d.AuditKey{
        .hash = z3d.g_edit_key_hash,
        .generation = z3d.g_edit_generation,
        .faces = face_count,
        .verts_digest = std.hash.Wyhash.hash(0, std.mem.sliceAsBytes(verts)),
    };
    if (z3d.g_audit_key) |cached| {
        if (cached.hash == key.hash and cached.generation == key.generation and
            cached.faces == key.faces and cached.verts_digest == key.verts_digest) return z3d.g_audit_facts;
    }
    // Glass faces do not block reachability rays (req_3763 P3-1): a glazed cabin's
    // interior is visible through the windows, so treating glass as opaque reported
    // every seat and dashboard as unreachable. The face colour's alpha channel IS
    // the durable glass state (model_paint.isGlassAlpha).
    const glass_rows: ?[]bool = allocator.alloc(bool, face_count) catch null;
    defer if (glass_rows) |rows| allocator.free(rows);
    var transparent: ?[]const bool = null;
    if (glass_rows) |rows| {
        var any_glass = false;
        for (rows, 0..) |*row, face| {
            const color = model_source.colorOf(@intCast(face));
            row.* = if (color) |c| model_paint.isGlassAlpha(c[3]) else false;
            if (row.*) any_glass = true;
        }
        if (any_glass) transparent = rows;
    }
    z3d.g_audit_facts = mesh_audit.audit(allocator, verts, face_count, .{}, transparent, .{});
    z3d.g_audit_key = key;
    return z3d.g_audit_facts;
}

pub fn meshSemanticStateJson(allocator: std.mem.Allocator) ?[]u8 {
    const verts = z3d.g_edit_verts orelse return null;
    const regions = model_source.faceSemanticRegions();
    const instances = model_source.faceSemanticInstances();
    const face_count: usize = @intCast(z3d.g_edit_count / 3);
    const face_groups = z3d.captureFaceGroups() orelse return null;
    defer std.heap.c_allocator.free(face_groups);
    const authored_faces = mesh_edit.authoredFaceCountFromGroups(face_groups) orelse return null;
    var aggregates = std.AutoHashMapUnmanaged(u32, z3d.SemanticPerceptAggregate).empty;
    defer aggregates.deinit(allocator);
    var instance_keys = std.AutoHashMapUnmanaged(u64, void).empty;
    defer instance_keys.deinit(allocator);
    var unnamed: u32 = 0;
    if (regions) |region_rows| {
        const instance_rows = instances orelse return null;
        if (region_rows.len != face_count or instance_rows.len != face_count) return null;
        for (region_rows, instance_rows, 0..) |region, instance, face| {
            if (region == model_source.NO_SEMANTIC_ID) {
                unnamed += 1;
                continue;
            }
            const gop = aggregates.getOrPut(allocator, region) catch return null;
            if (!gop.found_existing) gop.value_ptr.* = .{};
            gop.value_ptr.faces += 1;
            const instance_key = (@as(u64, region) << 32) | instance;
            const instance_gop = instance_keys.getOrPut(allocator, instance_key) catch return null;
            if (!instance_gop.found_existing) gop.value_ptr.instances += 1;
            const base = face * 24;
            if (base + 24 > verts.len) return null;
            for (0..3) |corner| for (0..3) |axis| {
                const value = verts[base + corner * 8 + axis];
                gop.value_ptr.min[axis] = @min(gop.value_ptr.min[axis], value);
                gop.value_ptr.max[axis] = @max(gop.value_ptr.max[axis], value);
            };
        }
    } else unnamed = @intCast(face_count);

    var hidden_faces: u32 = 0;
    var hidden_named_faces: u32 = 0;
    var hidden_region_ids = std.AutoHashMapUnmanaged(u32, void).empty;
    defer hidden_region_ids.deinit(allocator);
    for (z3d.g_hidden_groups.items) |hidden| {
        hidden_faces += @intCast(hidden.semantic_regions.len);
        for (hidden.semantic_regions) |region| {
            if (region == model_source.NO_SEMANTIC_ID) continue;
            hidden_named_faces += 1;
            hidden_region_ids.put(allocator, region, {}) catch return null;
        }
    }

    const ids = allocator.alloc(u32, aggregates.count()) catch return null;
    defer allocator.free(ids);
    var id_index: usize = 0;
    var iterator = aggregates.keyIterator();
    while (iterator.next()) |id| {
        ids[id_index] = id.*;
        id_index += 1;
    }
    std.mem.sort(u32, ids, {}, std.sort.asc(u32));

    // Hard geometric facts, reported and never enforced (req_3749). `auditComputed`
    // false means the mesh was over budget: the counts are unmeasured, NOT zero, and
    // the reader must say so rather than imply a clean model.
    const facts = z3d.meshAuditFacts(allocator, verts, @intCast(face_count));

    var out: std.ArrayList(u8) = .empty;
    errdefer out.deinit(allocator);
    var head_buf: [384]u8 = undefined;
    const head = std.fmt.bufPrint(&head_buf, "{{\"version\":1,\"generation\":{d},\"faces\":{d},\"authoredFaces\":{d},\"unnamed\":{d},\"hiddenFaces\":{d},\"hiddenNamedFaces\":{d},\"hiddenRegions\":{d},\"auditComputed\":{s},\"intersectingFaces\":{d},\"unreachableFaces\":{d},\"auditDirections\":{d},\"regions\":[", .{
        z3d.g_edit_generation,
        face_count,
        authored_faces,
        unnamed,
        hidden_faces,
        hidden_named_faces,
        hidden_region_ids.count(),
        if (facts.computed) "true" else "false",
        facts.intersecting,
        facts.unreachable_faces,
        facts.directions,
    }) catch return null;
    out.appendSlice(allocator, head) catch return null;
    for (ids, 0..) |id, index| {
        const aggregate = aggregates.get(id) orelse continue;
        var row_buf: [320]u8 = undefined;
        const row = std.fmt.bufPrint(
            &row_buf,
            "{s}{{\"id\":{d},\"faces\":{d},\"instances\":{d},\"bbox\":[{d},{d},{d},{d},{d},{d}]}}",
            .{ if (index == 0) "" else ",", id, aggregate.faces, aggregate.instances, aggregate.min[0], aggregate.min[1], aggregate.min[2], aggregate.max[0], aggregate.max[1], aggregate.max[2] },
        ) catch return null;
        out.appendSlice(allocator, row) catch return null;
    }
    out.appendSlice(allocator, "],\"table\":") catch return null;
    out.appendSlice(allocator, model_source.semanticTableJson() orelse "{\"version\":1,\"regions\":[]}") catch return null;
    out.append(allocator, '}') catch return null;
    return out.toOwnedSlice(allocator) catch null;
}

pub const MeshSelectorKind = enum { all, region, region_facing, part, facing, above, below, extremal, box, mirror };
pub const MeshSelectorQuery = struct {
    kind: z3d.MeshSelectorKind,
    region: u32 = model_source.NO_SEMANTIC_ID,
    regions: []const u32 = &.{},
    lo: u32 = 0,
    hi: u32 = 0,
    axis: u8 = 1,
    sign: f32 = 1,
    tolerance_degrees: f32 = 15,
    threshold: f32 = 0,
    epsilon: f32 = 0.0001,
    min: [3]f32 = .{ 0, 0, 0 },
    max: [3]f32 = .{ 0, 0, 0 },
    additive: bool = false,
};
/// `unmatched_sources` only means anything for the `mirror` kind: how many faces of the
/// SOURCE selection found nothing standing at their reflection. A mirror that silently
/// pairs 20 of 24 faces reads exactly like a clean one until this number is looked at.
pub const MeshSelectorResult = struct { faces: u32, actionable_faces: u32, bbox: [6]f32, unmatched_sources: u32 = 0 };

pub fn selectorHasRegion(query: z3d.MeshSelectorQuery, region: u32) bool {
    if (query.regions.len == 0) return region == query.region;
    for (query.regions) |candidate| if (candidate == region) return true;
    return false;
}

pub fn triangleCentroidAxis(verts: []const f32, face: usize, axis: usize) f32 {
    const base = face * 24;
    return (verts[base + axis] + verts[base + 8 + axis] + verts[base + 16 + axis]) / 3;
}

pub fn centroidsCoincide(centroid: [3]f32, other: []const f32, tolerance: f32) bool {
    return @abs(centroid[0] - other[0]) <= tolerance and
        @abs(centroid[1] - other[1]) <= tolerance and
        @abs(centroid[2] - other[2]) <= tolerance;
}

/// Resolve a geometric/semantic selector against the live topology at use time.
/// No index is retained across mutations; the returned count/bounds state exactly
/// what the operation reached, which makes zero/over-broad resolutions visible.
pub fn meshSelectQuery(query: z3d.MeshSelectorQuery) ?z3d.MeshSelectorResult {
    const verts = z3d.g_edit_verts orelse return null;
    const face_count: usize = @intCast(z3d.g_edit_count / 3);
    if (face_count == 0 or query.axis > 2 or verts.len < face_count * 24) return null;
    const mask = z3d.jalloc.alloc(bool, face_count) catch return null;
    defer z3d.jalloc.free(mask);
    @memset(mask, false);
    const axis: usize = query.axis;
    var extremum: f32 = if (query.sign >= 0) -std.math.inf(f32) else std.math.inf(f32);
    if (query.kind == .extremal) for (0..face_count) |face| {
        const value = z3d.triangleCentroidAxis(verts, face, axis);
        extremum = if (query.sign >= 0) @max(extremum, value) else @min(extremum, value);
    };
    const facing_cos = @cos(std.math.degreesToRadians(std.math.clamp(query.tolerance_degrees, 0, 180)));
    // Mirror twins: reflect the CURRENT selection across the model-origin plane and take
    // whatever stands there. The pairing is positional — the same way mirror-quads and
    // mirror-replace already find twins — so an unnamed counterpart needs no name of its
    // own to be reached. Snapshot the sources before the loop, because the loop's own
    // clearSelection() is what the twins are about to be written into.
    const tolerance = @max(query.epsilon, 0);
    var mirror_sources: []f32 = &.{};
    var mirror_hit: []bool = &.{};
    defer if (mirror_sources.len > 0) z3d.jalloc.free(mirror_sources);
    defer if (mirror_hit.len > 0) z3d.jalloc.free(mirror_hit);
    if (query.kind == .mirror) {
        var sources: usize = 0;
        for (0..face_count) |face| {
            if (mesh_edit.faceSelectedPub(@intCast(face))) sources += 1;
        }
        if (sources == 0) return .{ .faces = 0, .actionable_faces = 0, .bbox = .{ 0, 0, 0, 0, 0, 0 } };
        mirror_sources = z3d.jalloc.alloc(f32, sources * 3) catch return null;
        mirror_hit = z3d.jalloc.alloc(bool, sources) catch return null;
        @memset(mirror_hit, false);
        var next: usize = 0;
        for (0..face_count) |face| {
            if (!mesh_edit.faceSelectedPub(@intCast(face))) continue;
            const slot = mirror_sources[next * 3 ..][0..3];
            for (0..3) |component| slot[component] = z3d.triangleCentroidAxis(verts, face, component);
            slot[axis] = -slot[axis];
            next += 1;
        }
    }
    var matched: u32 = 0;
    var actionable: u32 = 0;
    var bbox: [6]f32 = .{ std.math.inf(f32), std.math.inf(f32), std.math.inf(f32), -std.math.inf(f32), -std.math.inf(f32), -std.math.inf(f32) };
    for (0..face_count) |face| {
        const centroid = [3]f32{
            z3d.triangleCentroidAxis(verts, face, 0),
            z3d.triangleCentroidAxis(verts, face, 1),
            z3d.triangleCentroidAxis(verts, face, 2),
        };
        const include = switch (query.kind) {
            .all => true,
            .region => z3d.selectorHasRegion(query, model_source.faceSemanticOf(@intCast(face)).region),
            .region_facing => blk: {
                if (!z3d.selectorHasRegion(query, model_source.faceSemanticOf(@intCast(face)).region)) break :blk false;
                const base = face * 24;
                const a = [3]f32{ verts[base], verts[base + 1], verts[base + 2] };
                const b = [3]f32{ verts[base + 8], verts[base + 9], verts[base + 10] };
                const c = [3]f32{ verts[base + 16], verts[base + 17], verts[base + 18] };
                const normal = z3d.normalOf(a, b, c);
                break :blk normal[axis] * (if (query.sign >= 0) @as(f32, 1) else -1) >= facing_cos;
            },
            .part => blk: {
                const group = model_source.faceGroupOf(@intCast(face));
                break :blk group != model_source.NO_FACE_GROUP and group >= query.lo and group < query.hi;
            },
            .above => centroid[axis] > query.threshold,
            .below => centroid[axis] < query.threshold,
            .extremal => @abs(centroid[axis] - extremum) <= @max(query.epsilon, 0),
            .box => centroid[0] >= query.min[0] and centroid[0] <= query.max[0] and
                centroid[1] >= query.min[1] and centroid[1] <= query.max[1] and
                centroid[2] >= query.min[2] and centroid[2] <= query.max[2],
            .facing => blk: {
                const base = face * 24;
                const a = [3]f32{ verts[base], verts[base + 1], verts[base + 2] };
                const b = [3]f32{ verts[base + 8], verts[base + 9], verts[base + 10] };
                const c = [3]f32{ verts[base + 16], verts[base + 17], verts[base + 18] };
                const normal = z3d.normalOf(a, b, c);
                break :blk normal[axis] * (if (query.sign >= 0) @as(f32, 1) else -1) >= facing_cos;
            },
            // Every reflected source is scanned rather than stopping at the first hit, so
            // coincident faces (an inner skin behind an outer one) both come along and the
            // count says so, instead of half a surface arriving silently.
            .mirror => blk: {
                var twin = false;
                var source: usize = 0;
                while (source < mirror_hit.len) : (source += 1) {
                    const reflected = mirror_sources[source * 3 ..][0..3];
                    if (@abs(centroid[axis] - reflected[axis]) > tolerance) continue;
                    if (!z3d.centroidsCoincide(centroid, reflected, tolerance)) continue;
                    mirror_hit[source] = true;
                    twin = true;
                }
                break :blk twin;
            },
        };
        if (!include) continue;
        mask[face] = true;
        matched += 1;
        if (mesh_edit.faceInScopePub(@intCast(face))) actionable += 1;
        const base = face * 24;
        for (0..3) |corner| for (0..3) |component| {
            const value = verts[base + corner * 8 + component];
            bbox[component] = @min(bbox[component], value);
            bbox[component + 3] = @max(bbox[component + 3], value);
        };
    }
    if (!query.additive) mesh_edit.clearSelection();
    var first = !query.additive;
    for (mask, 0..) |selected, face| {
        if (!selected) continue;
        _ = mesh_edit.selectFaceByIndex(@intCast(face), !first);
        first = false;
    }
    if (matched == 0) bbox = .{ 0, 0, 0, 0, 0, 0 };
    var unmatched: u32 = 0;
    for (mirror_hit) |paired| {
        if (!paired) unmatched += 1;
    }
    return .{ .faces = matched, .actionable_faces = actionable, .bbox = bbox, .unmatched_sources = unmatched };
}

/// Select every point whose face corners carry MORE THAN ONE logical row (req_4206) —
/// the exact set that can block a fill, marked so it can be looked at instead of
/// theorised about.
///
/// These are NOT duplicate vertices, and calling them that was wrong: `stats anomalies`
/// reports zero coincident positions on the model that hit this. One position, several
/// logical vertices in the id namespace — whatever produced the split, it is a fact
/// about the row table, not about the geometry, and this reports only what it measures.
///
/// A count nobody can locate is not actionable — the rule `meshSelectAuditFaces`
/// follows — so this does not return a number to be believed, it puts the selection on
/// the points and lets the viewport settle the argument.
///
/// Returns null when there is no live mesh or no logical row table to compare against.
pub fn meshSelectSplitPoints() ?z3d.MeshSelectorResult {
    const rows = model_source.renderCornerLogicalIds() orelse return null;
    if (!mesh_edit.ensureTopologyPub() or rows.len != z3d.g_edit_count) return null;
    const face_count = z3d.g_edit_count / 3;
    const vertex_count = mesh_edit.vertCount();
    if (face_count == 0 or vertex_count == 0) return null;

    const allocator = std.heap.c_allocator;
    const first_row = allocator.alloc(u32, vertex_count) catch return null;
    defer allocator.free(first_row);
    const unmerged = allocator.alloc(bool, vertex_count) catch return null;
    defer allocator.free(unmerged);
    const NO_ROW = std.math.maxInt(u32);
    @memset(first_row, NO_ROW);
    @memset(unmerged, false);

    var face: u32 = 0;
    while (face < face_count) : (face += 1) {
        var corner: u32 = 0;
        while (corner < 3) : (corner += 1) {
            const vertex = mesh_edit.cornerVertPub(face, corner);
            if (vertex >= vertex_count) continue;
            const row = rows[@as(usize, face) * 3 + corner];
            if (first_row[vertex] == NO_ROW) {
                first_row[vertex] = row;
            } else if (first_row[vertex] != row) {
                unmerged[vertex] = true;
            }
        }
    }

    mesh_edit.setMode(.vertex);
    mesh_edit.clearSelection();
    var matched: u32 = 0;
    var actionable: u32 = 0;
    var bbox: [6]f32 = .{ std.math.inf(f32), std.math.inf(f32), std.math.inf(f32), -std.math.inf(f32), -std.math.inf(f32), -std.math.inf(f32) };
    var vertex: u32 = 0;
    while (vertex < vertex_count) : (vertex += 1) {
        if (!unmerged[vertex]) continue;
        _ = mesh_edit.selectVertexByIndex(vertex, matched != 0);
        matched += 1;
        if (mesh_edit.vertInScopePub(vertex)) actionable += 1;
        const at = mesh_edit.vertPosPub(vertex);
        for (0..3) |axis| {
            bbox[axis] = @min(bbox[axis], at[axis]);
            bbox[axis + 3] = @max(bbox[axis + 3], at[axis]);
        }
    }
    if (matched == 0) bbox = .{ 0, 0, 0, 0, 0, 0 };
    return .{ .faces = matched, .actionable_faces = actionable, .bbox = bbox };
}

/// Which audited fact to select. `both` is the union — one press to see every
/// triangle the SHAPE panel is complaining about.
pub const AuditSelectKind = enum(u8) { intersecting = 0, unreachable_faces = 1, both = 2 };

/// Select the triangles behind the SHAPE panel's geometry counts (req_3883). A count
/// the user cannot locate is not actionable: this re-runs the audit asking it to mark
/// the faces it counts, switches to face mode, and selects exactly that set — so the
/// number and the selection can never describe different triangles.
///
/// Returns null when there is no live mesh; a zero-face result when the audit was
/// over budget or the mesh is genuinely clean (the caller distinguishes those by
/// reading `auditComputed` from the percept it already has).
pub fn meshSelectAuditFaces(kind: z3d.AuditSelectKind) ?z3d.MeshSelectorResult {
    const verts = z3d.g_edit_verts orelse return null;
    const face_count_usize: usize = @intCast(z3d.g_edit_count / 3);
    if (face_count_usize == 0 or verts.len < face_count_usize * 24) return null;
    const face_count: u32 = @intCast(face_count_usize);

    const allocator = std.heap.c_allocator;
    const intersecting = allocator.alloc(bool, face_count_usize) catch return null;
    defer allocator.free(intersecting);
    const unreachable_faces = allocator.alloc(bool, face_count_usize) catch return null;
    defer allocator.free(unreachable_faces);

    // Glass is transparent to reachability exactly as the counting path treats it
    // (req_3763 P3-1), or the selection would offer up a glazed cabin's interior.
    const glass_rows: ?[]bool = allocator.alloc(bool, face_count_usize) catch null;
    defer if (glass_rows) |rows| allocator.free(rows);
    var transparent: ?[]const bool = null;
    if (glass_rows) |rows| {
        var any_glass = false;
        for (rows, 0..) |*row, face| {
            const color = model_source.colorOf(@intCast(face));
            row.* = if (color) |c| model_paint.isGlassAlpha(c[3]) else false;
            if (row.*) any_glass = true;
        }
        if (any_glass) transparent = rows;
    }

    const facts = mesh_audit.audit(allocator, verts, face_count, .{}, transparent, .{
        .intersecting = intersecting,
        .unreachable_faces = unreachable_faces,
    });
    if (!facts.computed) return z3d.MeshSelectorResult{ .faces = 0, .actionable_faces = 0, .bbox = .{ 0, 0, 0, 0, 0, 0 } };

    mesh_edit.setMode(.face);
    mesh_edit.clearSelection();
    var matched: u32 = 0;
    var actionable: u32 = 0;
    var bbox: [6]f32 = .{ std.math.inf(f32), std.math.inf(f32), std.math.inf(f32), -std.math.inf(f32), -std.math.inf(f32), -std.math.inf(f32) };
    for (0..face_count_usize) |face| {
        const wanted = switch (kind) {
            .intersecting => intersecting[face],
            .unreachable_faces => unreachable_faces[face],
            .both => intersecting[face] or unreachable_faces[face],
        };
        if (!wanted) continue;
        _ = mesh_edit.selectFaceByIndex(@intCast(face), matched != 0);
        matched += 1;
        if (mesh_edit.faceInScopePub(@intCast(face))) actionable += 1;
        const base = face * 24;
        for (0..3) |corner_index| for (0..3) |component| {
            const value = verts[base + corner_index * 8 + component];
            bbox[component] = @min(bbox[component], value);
            bbox[component + 3] = @max(bbox[component + 3], value);
        };
    }
    if (matched == 0) bbox = .{ 0, 0, 0, 0, 0, 0 };
    return .{ .faces = matched, .actionable_faces = actionable, .bbox = bbox };
}

/// Assign/clear a texture role on the CURRENT authored-face selection. Geometry and
/// paint pixels do not move; only indexed face metadata changes, and it journals with
/// the model so Undo cannot desynchronise the Rig panel from the meshdoc.
pub fn meshTextureSlotAssign(material: u32) u32 {
    if (!z3d.residentMutationAllowed(.durable_channels)) return 0;
    if (!model_paint.hasTarget() or mesh_edit.mode() != .face) return 0;
    const tri_count = z3d.g_edit_count / 3;
    if (tri_count == 0) return 0;
    const mask = std.heap.c_allocator.alloc(bool, tri_count) catch return 0;
    defer std.heap.c_allocator.free(mask);
    if (mesh_edit.buildDeleteMask(mask) == 0 or !z3d.ensureIndexedEditMesh()) return 0;
    var snap = z3d.journalSnapshotCurrent("texture slot");
    const changed = z3d.g_indexed_edit_mesh.?.assignSelectedMaterial(mask, material);
    if (changed == 0) {
        z3d.journalDiscard(&snap);
        return 0;
    }
    var lowered = z3d.g_indexed_edit_mesh.?.lower() catch {
        z3d.journalDiscard(&snap);
        return 0;
    };
    defer lowered.deinit();
    model_source.setFaceMaterials(lowered.materials);
    z3d.journalCommit(&snap);
    return changed;
}

/// Removing a named role compacts later indices and clears faces that wore it.
pub fn meshTextureSlotRemove(material: u32) u32 {
    if (!z3d.residentMutationAllowed(.durable_channels)) return 0;
    if (!z3d.ensureIndexedEditMesh()) return 0;
    var snap = z3d.journalSnapshotCurrent("remove texture slot");
    var changed: u32 = 0;
    for (z3d.g_indexed_edit_mesh.?.faces.items) |*face| {
        if (!face.alive or face.material == indexed_edit_mesh.NO_MATERIAL) continue;
        if (face.material == material) {
            face.material = indexed_edit_mesh.NO_MATERIAL;
            changed += 1;
        } else if (face.material > material) {
            face.material -= 1;
            changed += 1;
        }
    }
    if (changed == 0) {
        z3d.journalDiscard(&snap);
        return 0;
    }
    var lowered = z3d.g_indexed_edit_mesh.?.lower() catch {
        z3d.journalDiscard(&snap);
        return 0;
    };
    defer lowered.deinit();
    model_source.setFaceMaterials(lowered.materials);
    z3d.journalCommit(&snap);
    return changed;
}

pub fn meshTextureSlotSelect(material: u32) u32 {
    const tri_count = z3d.g_edit_count / 3;
    if (tri_count == 0) return 0;
    const mask = std.heap.c_allocator.alloc(bool, tri_count) catch return 0;
    defer std.heap.c_allocator.free(mask);
    var face: u32 = 0;
    while (face < tri_count) : (face += 1) mask[face] = model_source.faceMaterialOf(face) == material;
    return mesh_edit.selectFacesByTriangleMask(mask);
}
/// Adopt the outliner's part ranges (flattened [lo,hi) group-id pairs) and rebuild the
/// welded topology, so coincident verts in DIFFERENT parts stay separate logical verts.
/// This is also where a PERSISTED doc's ranges arrive on load/resume — a doc saved
/// while the req_3029 minting bug was live heals here instead of reopening corrupt.
pub fn meshEditSetPartRanges(pairs: []const u32) void {
    if (!z3d.residentMutationAllowed(.durable_channels)) return;
    z3d.clearIndexedEditMesh();
    // Tripwire (req_3049): a session lost its host part ranges and the next save
    // persisted a doc that reopens with every part merged. An empty push over a mesh
    // that HAS ranges is the one legal way to clear them — name it when it happens.
    if (pairs.len < 2 and model_source.partRanges() != null) {
        log.print("[mesh] part ranges CLEARED by an empty cart push over a mesh that had {d} parts — if unintended this is the req_3049 merged-outliner save corruption\n", .{model_source.partRanges().?.len / 2});
    }
    // One-part recovery is exact, not a guess: a fresh Create Face group cannot
    // belong anywhere else. Older/hot sessions could re-push the pre-op [lo,hi)
    // and strand that face outside the edit scope; the next save then refused
    // because the part owned N-1/N faces. Heal that stale mirror at its boundary.
    var healed: [2]u32 = undefined;
    var installed = pairs;
    if (pairs.len == 2) {
        if (z3d.captureFaceGroups()) |groups| {
            defer std.heap.c_allocator.free(groups);
            if (mesh_journal_log.healedSinglePartRange(groups, pairs)) |range| {
                healed = range;
                installed = healed[0..];
                log.print("[mesh] expanded the sole part range [{d},{d}) → [{d},{d}) to adopt freshly minted face groups\n", .{
                    pairs[0], pairs[1], healed[0], healed[1],
                });
            }
        }
    }
    model_source.setPartRanges(installed);
    _ = z3d.ensureDisjointPartRanges("cart range push");
    mesh_edit.reset();
}
/// Count the surviving faces whose authored group is in [lo, hi) — the outliner asks this
/// after a delete to drop parts that have no geometry left.
pub fn meshGroupFaceCount(lo: u32, hi: u32) u32 {
    const fc = model_paint.faceCount();
    var n: u32 = 0;
    var f: u32 = 0;
    while (f < fc) : (f += 1) {
        const grp = model_source.faceGroupOf(f);
        if (grp != model_source.NO_FACE_GROUP and grp >= lo and grp < hi) n += 1;
    }
    return n;
}
/// Paint every face in the authored group range [lo, hi) a solid colour — the outliner tints
/// each PART its own colour on load so a bare studio mesh reads as coloured parts, matching
/// the outliner swatches. Returns the number of faces painted.
pub fn meshPaintGroupRange(lo: u32, hi: u32, r: u8, g: u8, b: u8) u32 {
    if (!z3d.residentMutationAllowed(.paint_raster)) return 0;
    if (z3d.g_paint_layout_stale) return 0;
    const fc = model_paint.faceCount();
    // Painting a selection-tinted face must land UNDER the tint (the outliner can recolor
    // a part while its faces are selected): lift the tint, paint, re-apply — the re-saved
    // base patch then holds the new paint, so a later deselect keeps it.
    mesh_edit.suspendFaceTint();
    defer mesh_edit.resumeFaceTint();
    var painted: u32 = 0;
    var f: u32 = 0;
    while (f < fc) : (f += 1) {
        const grp = model_source.faceGroupOf(f);
        if (grp == model_source.NO_FACE_GROUP or grp < lo or grp >= hi) continue;
        model_paint.paintFaceRgb(f, .{ r, g, b });
        model_source.writeColor(@intCast(f), r, g, b);
        painted += 1;
    }
    return painted;
}

/// Journaled solid-colour fill of the current authored-face selection. This is
/// the coordinate-free paint boundary used by automation: selection supplies the
/// noun, RGB supplies the material fact, and no viewport raycast is involved.
pub fn meshPaintSelection(io: std.Io, environ: *const std.process.Environ.Map, r: u8, g: u8, b: u8) u32 {
    if (!z3d.residentMutationAllowed(.paint_raster)) return 0;
    if (z3d.g_paint_layout_stale or !model_paint.hasTarget() or mesh_edit.mode() != .face) return 0;
    const face_count = z3d.g_edit_count / 3;
    if (face_count == 0) return 0;
    const mask = z3d.jalloc.alloc(bool, face_count) catch return 0;
    defer z3d.jalloc.free(mask);
    if (mesh_edit.buildDeleteMask(mask) == 0) return 0;
    // Mirror (req_3797): the fill paints the twin faces too — the mirror-painting half
    // of req_1538's original ask, for fills.
    if (mesh_edit.mirrorMask() != 0) {
        if (z3d.g_edit_verts) |soup| z3d.extendFaceMaskWithMirrorTwins(soup, face_count, mask);
    }
    var snap = z3d.journalSnapshotForNewAction(mesh_journal_log.PAINT_FACES_LABEL);
    if (snap == null or snap.?.atlas == null or snap.?.paint_state == null) {
        z3d.journalDiscard(&snap);
        return 0;
    }
    paint_program.beginRecordedOp();
    mesh_edit.suspendFaceTint();
    defer mesh_edit.resumeFaceTint();
    var painted: u32 = 0;
    for (mask, 0..) |selected, face| {
        if (!selected) continue;
        model_paint.paintFaceRgb(@intCast(face), .{ r, g, b });
        model_source.writeColor(@intCast(face), r, g, b);
        paint_program.recordFill(@intCast(face), false, .{ r, g, b });
        painted += 1;
    }
    if (painted == 0) {
        z3d.journalDiscard(&snap);
        return 0;
    }
    if (!z3d.paintStrokeEnd(io, environ)) {
        if (snap) |*entry| _ = z3d.journalInstall(entry);
        z3d.journalDiscard(&snap);
        return 0;
    }
    z3d.journalCommit(&snap);
    return painted;
}
/// Select an edge by welded-edge index (no raycast) — programmatic / headless.
pub fn meshEditSelectEdge(idx: u32, additive: bool) bool {
    return mesh_edit.selectEdgeByIndex(idx, additive);
}

/// On-demand topology vocabulary for agents. Indices are explicitly ephemeral:
/// callers re-read this after every topology generation instead of retaining them.
pub fn meshEditElementsJson(allocator: std.mem.Allocator) ?[]u8 {
    if (!model_paint.hasTarget() or !mesh_edit.ensureTopologyPub()) return null;
    var out: std.Io.Writer.Allocating = .init(allocator);
    defer out.deinit();
    const writer = &out.writer;
    // Scope-honouring (req_3763 P2-1): when a part scope is active, only in-scope
    // elements emit — ids stay GLOBAL (stable handles for select-vertex/edge), so
    // a scoped read is a filter, never a renumbering. An unscoped mesh still
    // returns everything; large whole-mesh reads should page via follow inspect.
    writer.writeAll("{\"vertices\":[") catch return null;
    var vertex_emitted: u32 = 0;
    var vertex: u32 = 0;
    while (vertex < mesh_edit.vertCount()) : (vertex += 1) {
        if (!mesh_edit.vertInScopePub(vertex)) continue;
        const p = mesh_edit.vertPosPub(vertex);
        writer.print("{s}{s}\"id\":{d},\"at\":[{d},{d},{d}]}}", .{ if (vertex_emitted == 0) "" else ",", "{", vertex, p[0], p[1], p[2] }) catch return null;
        vertex_emitted += 1;
    }
    writer.writeAll("],\"edges\":[") catch return null;
    var emitted: u32 = 0;
    var edge: u32 = 0;
    while (edge < mesh_edit.edgeCount()) : (edge += 1) {
        if (!mesh_edit.edgeIsBoundaryPub(edge)) continue;
        if (!mesh_edit.edgeInScopePub(edge)) continue;
        const endpoints = mesh_edit.edgeEndpointsPub(edge);
        const incidence = mesh_edit.edgeFaceIncidencePub(edge);
        const open = incidence == 1 and !mesh_edit.edgeIsWirePub(edge);
        writer.print("{s}{s}\"id\":{d},\"vertices\":[{d},{d}],\"faces\":{d},\"open\":{s}}}", .{
            if (emitted == 0) "" else ",", "{", edge, endpoints[0], endpoints[1], incidence, if (open) "true" else "false",
        }) catch return null;
        emitted += 1;
    }
    writer.writeAll("]}") catch return null;
    return out.toOwnedSlice() catch null;
}

/// Compact, selection-only topology facts for the visible Model Focus inspector and
/// coordinate-free Agent Seat reads. The mesh-edit module owns the schema so every
/// consumer sees the same selected ids, geometry, topology, material, and semantics.
pub fn meshEditSelectionJson(allocator: std.mem.Allocator) ?[]u8 {
    if (!model_paint.hasTarget()) return null;
    return mesh_edit.selectionSnapshotJson(allocator);
}

pub fn retopoBandPlanJson(allocator: std.mem.Allocator) ?[]u8 {
    const plan = if (z3d.g_retopo_band_plan) |*value| value else return null;
    if (plan.faces.len != model_paint.faceCount()) return null;
    var out: std.Io.Writer.Allocating = .init(allocator);
    defer out.deinit();
    const writer = &out.writer;
    const axis_name: []const u8 = switch (plan.axis) {
        0 => "x",
        1 => "y",
        else => "z",
    };
    const mode_name: []const u8 = if (plan.mode == .rails) "rails" else "axis";
    writer.print("{{\"version\":1,\"mode\":\"{s}\",\"axis\":\"{s}\",\"width\":{d},\"origin\":{d},\"railSamples\":{d},\"faces\":{d},\"covered\":{d},\"bands\":[", .{
        mode_name, axis_name, plan.width, plan.origin, plan.rail_samples, plan.faces.len, plan.faces.len,
    }) catch return null;
    for (plan.bands, 0..) |band, at| {
        const color = z3d.retopoBandColor(band.id);
        writer.print(
            "{s}{{\"id\":{d},\"bucket\":{d},\"faces\":{d},\"range\":[{d},{d}],\"bbox\":[{d},{d},{d},{d},{d},{d}],\"color\":[{d},{d},{d}]}}",
            .{ if (at == 0) "" else ",", band.id, band.bucket, band.faces, band.range[0], band.range[1], band.bbox[0], band.bbox[1], band.bbox[2], band.bbox[3], band.bbox[4], band.bbox[5], color[0], color[1], color[2] },
        ) catch return null;
    }
    writer.writeAll("]}") catch return null;
    return out.toOwnedSlice() catch null;
}

pub fn retopoManualBandsJson(allocator: std.mem.Allocator) ?[]u8 {
    const labels = z3d.g_retopo_manual_bands orelse return null;
    const positions = model_paint.positions() orelse return null;
    const face_count = model_paint.faceCount();
    if (labels.len != face_count or positions.len < labels.len * 9) return null;
    var counts = [_]u32{0} ** z3d.RETOPO_BAND_PALETTE.len;
    var bboxes: [z3d.RETOPO_BAND_PALETTE.len][6]f32 = undefined;
    for (&bboxes) |*bbox| bbox.* = .{
        std.math.inf(f32),  std.math.inf(f32),  std.math.inf(f32),
        -std.math.inf(f32), -std.math.inf(f32), -std.math.inf(f32),
    };
    var covered: u32 = 0;
    for (labels, 0..) |label, face| {
        if (label == mesh_edit.RETOPO_BAND_UNASSIGNED or label >= z3d.RETOPO_BAND_PALETTE.len) continue;
        counts[label] += 1;
        covered += 1;
        const base = face * 9;
        for (0..3) |corner| {
            const at = base + corner * 3;
            bboxes[label][0] = @min(bboxes[label][0], positions[at]);
            bboxes[label][1] = @min(bboxes[label][1], positions[at + 1]);
            bboxes[label][2] = @min(bboxes[label][2], positions[at + 2]);
            bboxes[label][3] = @max(bboxes[label][3], positions[at]);
            bboxes[label][4] = @max(bboxes[label][4], positions[at + 1]);
            bboxes[label][5] = @max(bboxes[label][5], positions[at + 2]);
        }
    }
    var out: std.Io.Writer.Allocating = .init(allocator);
    defer out.deinit();
    const writer = &out.writer;
    writer.print("{{\"version\":1,\"mode\":\"manual\",\"axis\":\"y\",\"width\":0,\"origin\":0,\"railSamples\":0,\"faces\":{d},\"covered\":{d},\"bands\":[", .{ face_count, covered }) catch return null;
    var emitted: u32 = 0;
    for (counts, 0..) |count, id| {
        if (count == 0) continue;
        const color = z3d.retopoBandColor(@intCast(id));
        const bbox = bboxes[id];
        writer.print(
            "{s}{{\"id\":{d},\"bucket\":{d},\"faces\":{d},\"range\":[0,0],\"bbox\":[{d},{d},{d},{d},{d},{d}],\"color\":[{d},{d},{d}]}}",
            .{ if (emitted == 0) "" else ",", id, id, count, bbox[0], bbox[1], bbox[2], bbox[3], bbox[4], bbox[5], color[0], color[1], color[2] },
        ) catch return null;
        emitted += 1;
    }
    writer.writeAll("]}") catch return null;
    return out.toOwnedSlice() catch null;
}

/// Build and install a complete, preview-only axis-band plan. Width is metres;
/// origin may pin the phase to a user-approved strip.
pub fn meshRetopoBandsPlanJson(allocator: std.mem.Allocator, axis: u8, width: f32, origin: ?f32) ?[]u8 {
    const positions = model_paint.positions() orelse return null;
    const plan = mesh_edit.planRetopoAxisBands(std.heap.c_allocator, positions, model_paint.faceCount(), axis, width, origin) catch return null;
    var snap: ?z3d.JournalEntry = z3d.journalSnapshotCurrent(mesh_journal_log.RETOPO_GUIDE_PLAN_LABEL) orelse {
        var rejected = plan;
        rejected.deinit(std.heap.c_allocator);
        return null;
    };
    defer z3d.journalDiscard(&snap);
    _ = z3d.clearRetopoBandPreview();
    if (!z3d.captureRetopoSourceGhost(plan.faces)) {
        var rejected = plan;
        rejected.deinit(std.heap.c_allocator);
        z3d.restoreRetopoGuideAndDiscard(&snap);
        return null;
    }
    z3d.g_retopo_band_plan = plan;
    z3d.journalCommit(&snap);
    return z3d.retopoBandPlanJson(allocator);
}

pub fn meshRetopoBandsPlanRailsJson(allocator: std.mem.Allocator, rail_pairs: []const f32) ?[]u8 {
    const positions = model_paint.positions() orelse return null;
    const plan = mesh_edit.planRetopoRailBands(std.heap.c_allocator, positions, model_paint.faceCount(), rail_pairs) catch return null;
    var snap: ?z3d.JournalEntry = z3d.journalSnapshotCurrent(mesh_journal_log.RETOPO_GUIDE_PLAN_LABEL) orelse {
